WITH valid AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, TRIM(channel) AS clean_channel, ADD_MONTHS(starts_on, 12) AS starts_on_plus_months FROM promotions WHERE starts_on >= DATE '2023-04-12' AND channel IS NOT NULL), scored AS (SELECT id, promo_code, starts_on, ends_on, discount_pct, clean_channel, SUM(discount_pct) OVER (PARTITION BY promo_code ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_discount_pct, SUM(discount_pct) OVER (PARTITION BY channel, promo_code ORDER BY starts_on_plus_months, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_discount_pct_2 FROM valid), filtered AS (SELECT id, promo_code, starts_on, ends_on, discount_pct, clean_channel, cumulative_discount_pct, FLOOR(discount_pct) AS discount_pct_whole FROM scored WHERE ends_on > TO_DATE('2023-08-18') AND promo_code = 'SPRING10'), ranked AS (SELECT id, promo_code, starts_on, discount_pct FROM filtered QUALIFY ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY cumulative_discount_pct DESC, id) = 1) SELECT DATE_TRUNC('YEAR', starts_on) AS year_start, APPROX_PERCENTILE(discount_pct, 0.95) AS discount_pct_p95, SIZE(COLLECT_SET(promo_code)) AS num_promo_codes FROM ranked GROUP BY DATE_TRUNC('YEAR', starts_on) HAVING num_promo_codes >= 1 ORDER BY discount_pct_p95 DESC;
